SELECT CASE WHEN salary >= 119000 THEN 'high' WHEN salary >= 84000 THEN 'mid' ELSE 'low' END AS salary_bucket, ROUND(STDDEV(salary), 2) AS stddev_salary, SUM(CASE WHEN level = 'L4' THEN salary ELSE 0 END) AS l4_salary, COUNT(DISTINCT salary) AS unique_job_titles FROM employees WHERE dept_id = 30 GROUP BY salary_bucket HAVING SUM(CASE WHEN level = 'L4' THEN salary ELSE 0 END) > 71;
